/** 실패 자리의 다시 시도 버튼이 사라질 때만 결과로 focus를 옮긴다. */
import type { ReactNode } from 'react';
import { useRetryFocus } from '@boosterlab/web-kit/record';
/** 재시도 전에 다른 곳으로 이동한 focus는 빼앗지 않는다. */
export function RetryRegion({
  failed,
  message,
  onRetry,
  controlId,
  children,
  retryLabel = '다시 시도',
}: {
  readonly failed: boolean;
  readonly message?: ReactNode;
  readonly onRetry: () => void;
  readonly controlId: string;
  readonly children: ReactNode;
  readonly retryLabel?: string;
}) {
  const { retryRef } = useRetryFocus(failed, controlId);
  if (!failed) return children;
  return (
    <div role="alert">
      {message}
      <button type="button" ref={retryRef} className="wk-button" onClick={onRetry}>
        {retryLabel}
      </button>
    </div>
  );
}

// @vitest-environment jsdom
// 파일 책임: 설치한 retry 복사본을 키트 공통 단위 검사에 연결한다.
import { RetryRegion } from '../ui/retry';
import { checkRetryConformance } from '@boosterlab/web-kit/testing/unit';
import installation from '../../../../../registry-installation.json';
checkRetryConformance({ RetryRegion }, { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit });
